// Написан вручную (запасной путь: MCP-генератор не нашёл seed). Селекторы сверены на живой странице через playwright-cli
// (iPhone 13 Mini, free, 2026-10-29), сам тест не прогонялся — проверить при первом /qa-regress.
// spec: .qa/e2e/specs/location-map.md 2.1 · кейс .qa/tests/location-map/IND-01.md
// seed: tests/seed.free.geo.spec.ts
// Шит «דייט עכשיו» только открывается и закрывается (Escape) — режим не включается.
import { test, expect, type Request } from '@playwright/test';
import path from 'path';
import { disableSharing } from './map-helpers';
import { saveSession } from '../_shared/session';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/free.json'),
  viewport: { width: 390, height: 844 },
  hasTouch: true,
  geolocation: { latitude: 32.0853, longitude: 34.7818, accuracy: 10 },
  permissions: ['geolocation'],
});

// Текст индикатора — только точное совпадение: в шите есть строка «דייט עכשיו דורש שיתוף מיקום פעיל».
const PILL = 'שיתוף מיקום פעיל';
const OFF = 'שיתוף מיקום כבוי';

test.describe('Индикатор шаринга местоположения', () => {
  test('Шаринг выключен — индикатора нет на /map, /nearby и в шите Date Now @iphone @data (#5f64d4)', async ({ page }) => {
    try {
      // 1. /map; если шаринг включён — выключить (предусловие)
      await disableSharing(page);
      await expect(page.getByText(OFF, { exact: true })).toBeVisible();
      await expect(page.getByRole('button', { name: 'הפעלת שיתוף מיקום' })).toBeVisible();
      await expect(page.getByText(PILL, { exact: true })).toHaveCount(0);

      // 2. С этого момента — ни одного PATCH share_location
      const sharePatches: Request[] = [];
      page.on('request', (r) => {
        if (r.method() === 'PATCH' && r.url().includes('/rest/v1/profiles') && (r.postData() ?? '').includes('share_location')) sharePatches.push(r);
      });

      // 3. /nearby («מי היה לידי») — индикатора нет, кнопку включения не нажимаем
      await page.goto('/nearby');
      await expect(page.getByText('אנשים שהיו בקרבתך ב-7 השעות האחרונות')).toBeVisible();
      await expect(page.getByText(PILL, { exact: true })).toHaveCount(0);

      // 4. /map → шит «דייט עכשיו»: нет ни «שיתוף מיקום פעיל», ни «שיתוף מיקום כבוי» (реджект rej_e2aec356 п.1)
      await page.goto('/map');
      await expect(page.getByText(OFF, { exact: true })).toBeVisible();
      await page.getByRole('button', { name: 'דייט עכשיו' }).first().click();
      const sheet = page.getByRole('dialog').filter({ hasText: 'פנוי/ה לדייט עכשיו?' });
      await expect(sheet).toBeVisible();
      await expect(sheet.getByText(PILL, { exact: true })).toHaveCount(0);
      await expect(sheet.getByText(OFF, { exact: true })).toHaveCount(0);
      await page.keyboard.press('Escape');
      await expect(sheet).toBeHidden();

      expect(sharePatches, 'PATCH share_location за шаги 3–4').toHaveLength(0);
    } finally {
      await saveSession(page, 'free');
    }
  });
});
